#include "../wiegand.h"

static void wiegand_read_draw(App* app) {
    char levels[24];
    wiegand_levels_text(app->levels, levels, sizeof(levels));

    widget_reset(app->widget);
    widget_add_string_element(app->widget, 0, 0, AlignLeft, AlignTop, FontPrimary, "Read Wiegand");
    widget_add_string_element(
        app->widget, 0, 14, AlignLeft, AlignTop, FontSecondary, "Waiting for signal...");
    widget_add_string_element(app->widget, 0, 25, AlignLeft, AlignTop, FontSecondary, levels);
    widget_add_string_element(
        app->widget,
        0,
        35,
        AlignLeft,
        AlignTop,
        FontSecondary,
        (app->levels == 3) ? "Idle bus looks OK" : "LO at idle: pull-up/power?");
    widget_add_string_element(
        app->widget, 0, 46, AlignLeft, AlignTop, FontSecondary, "D0/Green/A4");
    widget_add_string_element(
        app->widget, 0, 55, AlignLeft, AlignTop, FontSecondary, "D1/White/A7");
}

void wiegand_read_scene_on_enter(void* context) {
    App* app = context;
    wiegand_scene_capture_start(app);
    wiegand_read_draw(app);
    view_dispatcher_switch_to_view(app->view_dispatcher, WiegandWidgetView);
}

bool wiegand_read_scene_on_event(void* context, SceneManagerEvent event) {
    App* app = context;
    if(event.type != SceneManagerEventTypeCustom) return false;

    if(event.event == WiegandCaptureFrameEvent) {
        if(wiegand_capture_has_frame()) {
            notification_message(app->notifications, &sequence_single_vibro);
            app->status[0] = '\0'; /* new frame: nothing saved or exported yet */
            scene_manager_next_scene(app->scene_manager, WiegandDataScene);
        }
        return true;
    }
    if(event.event == WiegandCaptureLevelEvent) {
        wiegand_read_draw(app);
        return true;
    }
    return false;
}

void wiegand_read_scene_on_exit(void* context) {
    App* app = context;
    wiegand_scene_capture_stop(app);
}
